import{_ as t,o as s,c as n,ah as o}from"./chunks/framework.BsNNkeaH.js";const g=JSON.parse('{"title":"Requests","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/parent/demarches.md","filePath":"src/en/guide/parent/demarches.md"}'),r={name:"en/guide/parent/demarches.md"};function i(a,e,l,d,c,u){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="requests" tabindex="-1">Requests <a class="header-anchor" href="#requests" aria-label="Permalink to &quot;Requests&quot;">​</a></h1><p>This page covers two requests you can make yourself for a child, without going through the school office: justifying an absence and requesting a site transfer.</p><h2 id="justifying-an-absence" tabindex="-1">Justifying an absence <a class="header-anchor" href="#justifying-an-absence" aria-label="Permalink to &quot;Justifying an absence&quot;">​</a></h2><p>When your child has been marked absent or late, you can send a justification directly from their record:</p><ol><li>On the child&#39;s record, go to the <strong>Attendance</strong> section.</li><li>Find the row for the day in question (status <strong>Absent</strong> or <strong>Late</strong>) and click <strong>Justify</strong>.</li><li>In the <strong>Justify this absence</strong> window, enter the <strong>Reason</strong>.</li><li>If you have a supporting document (a medical certificate, for example), attach it under <strong>Supporting document</strong> — accepted formats: PDF, JPG or PNG. This field is optional.</li><li>Click <strong>Send</strong>.</li></ol><p>Your justification then shows the status <strong>Awaiting review</strong>. The school reviews it and moves it to <strong>Justified</strong> or <strong>Rejected</strong>; the status updates directly on your child&#39;s record.</p><h2 id="requesting-a-site-transfer" tabindex="-1">Requesting a site transfer <a class="header-anchor" href="#requesting-a-site-transfer" aria-label="Permalink to &quot;Requesting a site transfer&quot;">​</a></h2><p>If you want to enroll your child at another site of the school (a different campus, for example), you can submit a transfer request:</p><ol><li>On the child&#39;s record, go to the <strong>Inter-site mobility</strong> section.</li><li>Click <strong>Request a transfer</strong> — this button is only available if no request is already pending for this child.</li><li>In the <strong>Request an inter-site transfer</strong> window, choose the <strong>Destination site</strong> and <strong>Destination department</strong> you want.</li><li>Add a <strong>Reason</strong> if you wish (optional).</li><li>Click <strong>Send request</strong>.</li></ol><p>The request appears in the table below with the date, origin site, destination site and its status: <strong>Pending</strong>, <strong>Approved</strong> or <strong>Rejected</strong>. While a request is pending, you cannot submit a new one for the same child.</p>',10)])])}const f=t(r,[["render",i]]);export{g as __pageData,f as default};
